#import <Foundation/Foundation.h>
#import <Vision/Vision.h>
#import <CoreImage/CoreImage.h>
int main(int argc,const char **argv){@autoreleasepool{if(argc!=3)return 2;NSString *in=@(argv[1]),*out=@(argv[2]);[[NSFileManager defaultManager]createDirectoryAtPath:out withIntermediateDirectories:YES attributes:nil error:nil];NSArray *fs=[[NSFileManager defaultManager]contentsOfDirectoryAtPath:in error:nil];CIContext *ctx=[CIContext context];CGColorSpaceRef cs=CGColorSpaceCreateDeviceGray();int n=0,bad=0;for(NSString *f in fs){if(![f.pathExtension.lowercaseString isEqual:@"png"])continue;n++;NSURL *u=[NSURL fileURLWithPath:[in stringByAppendingPathComponent:f]];CIImage *im=[CIImage imageWithContentsOfURL:u];VNGeneratePersonSegmentationRequest *r=[VNGeneratePersonSegmentationRequest new];r.qualityLevel=VNGeneratePersonSegmentationRequestQualityLevelAccurate;r.outputPixelFormat=kCVPixelFormatType_OneComponent8;NSError *e=nil;VNImageRequestHandler*h=[[VNImageRequestHandler alloc]initWithCIImage:im options:@{}];[h performRequests:@[r] error:&e];if(e||!r.results.count){bad++;continue;}CVPixelBufferRef pb=((VNPixelBufferObservation*)r.results[0]).pixelBuffer;CIImage *m=[CIImage imageWithCVPixelBuffer:pb];NSURL *dst=[NSURL fileURLWithPath:[out stringByAppendingPathComponent:f]];if(![ctx writePNGRepresentationOfImage:m toURL:dst format:kCIFormatL8 colorSpace:cs options:@{} error:&e])bad++;}CGColorSpaceRelease(cs);printf("masks: %d, failed: %d\n",n,bad);return bad?1:0;}}
